 internal static string SelectUnique(string name,IEnumerable<string> paths){string hit=null;foreach(string file in paths){bool exact=String.Equals(Path.GetFileName(file),name,StringComparison.OrdinalIgnoreCase),stem=String.IsNullOrEmpty(Path.GetExtension(name))&&String.Equals(Path.GetFileNameWithoutExtension(file),name,StringComparison.OrdinalIgnoreCase);if(!exact&&!stem)continue;if(hit!=null&&!String.Equals(hit,file,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Archivdatei mehrfach gefunden; keine automatische Auswahl.");hit=file;}if(hit==null)throw new FileNotFoundException();return hit;}
